referenceSolutions.javascript:
function branchNotebookPeakTicket(root, k) {
  const a=root; let out=[];
  function visit(node){if(!node)return;out.push(node.val);visit(node.left);visit(node.right);}visit(a);
  let answer=out.length?out[0]:0;for(const x of out)if(x>answer)answer=x;return answer;
}

